window.WAREVENTS = (window.WAREVENTS || []).concat([
  ['1916-06-10','10 juni 1916','Arabische Opstand','Sharif Hoessein van Mekka kwam in opstand tegen het Ottomaanse Rijk, met Britse steun en Britse beloften van Arabische onafhankelijkheid. Arabische strijders vielen de Hejaz-spoorlijn aan en trokken in 1918 Damascus binnen.','flag','m','Welke Britse officier werd bekend als verbindingsman bij de Arabische Opstand?',['Lord Kitchener','T.E. Lawrence','Edmund Allenby'],1],
  ['1916-07-01','1 juli – 18 november 1916','De Somme','Brits-Franse troepen vielen de Duitse linies langs de rivier de Somme aan. Op de eerste dag leden de Britten ca. 57.000 slachtoffers, het bloedigste dagtotaal in hun militaire geschiedenis. Na vier maanden waren de geallieerden hooguit ongeveer tien kilometer opgeschoven.','sword','w','Welk nieuw wapen werd tijdens de Slag aan de Somme voor het eerst ingezet?',['De tank','Het gifgas','De vlammenwerper'],0],
  ['1916-12-01','1916 – 1917','Steekrapenwinter','Na een mislukte aardappeloogst en door de Britse zeeblokkade leden Duitse steden in de winter van 1916 op 1917 grote honger. Steekrapen, eigenlijk veevoer, werden het hoofdvoedsel. Ondervoeding maakte vooral ouderen en kinderen kwetsbaar voor ziekte.','fire','h','Welke twee oorzaken leidden tot de Steekrapenwinter in Duitsland?',['Een droge zomer en een staking van boeren','Een mislukte aardappeloogst en de Britse zeeblokkade','Een Russische inval en de griep'],1],
  ['1917-02-01','1 februari 1917','Onbeperkte duikbootoorlog','Duitsland besloot alle schepen in de zone rond Groot-Brittannië zonder waarschuwing aan te vallen, ook die van neutrale landen. Het hoopte Groot-Brittannië binnen enkele maanden uit te hongeren. Het risico dat de Verenigde Staten de oorlog in zouden gaan, nam het voor lief.','ship','z','Welke maatregel van de geallieerden verminderde vanaf 1917 de scheepsverliezen het sterkst?',['Het konvooisysteem','Het mijnen van de Noordzee','Het bewapenen van vissersboten'],0],
  ['1917-03-08','8 – 15 maart 1917','Februarirevolutie in Rusland','In Petrograd liepen protesten tegen voedseltekorten uit op een opstand, waarbij soldaten de kant van de demonstranten kozen. Tsaar Nicolaas II deed afstand van de troon en een Voorlopige Regering nam de macht over. Rusland bleef echter meevechten in de oorlog.','flag','o','Waarom heet deze revolutie in maart 1917 de Februarirevolutie?',['Omdat de tsaar in februari was vertrokken','Omdat Rusland nog de juliaanse kalender gebruikte','Omdat de eerste staking in februari 1916 was'],1],
  ['1917-04-06','6 april 1917','Amerika gaat de oorlog in','De Verenigde Staten verklaarden Duitsland de oorlog, na de onbeperkte duikbootoorlog en het onderschepte Zimmermanntelegram. President Wilson sprak van een oorlog om de wereld veilig te maken voor democratie. In 1918 stonden ongeveer twee miljoen Amerikaanse soldaten in Frankrijk.','flag','p','Welk land kreeg in het Zimmermanntelegram een bondgenootschap met Duitsland aangeboden?',['Japan','Spanje','Mexico'],2],
  ['1917-04-16','16 april 1917','Afrikaanse soldaten aan het Westfront','Bij het Franse offensief aan de Chemin des Dames vochten duizenden West-Afrikaanse tirailleurs sénégalais in de voorste linies en leden zware verliezen. Frankrijk zette in de oorlog honderdduizenden soldaten uit zijn Afrikaanse koloniën in. Velen waren gedwongen geronseld.','person','k','Welke Senegalese politicus wierf in 1918 tienduizenden extra soldaten in Frans West-Afrika?',['Léopold Senghor','Blaise Diagne','Lamine Guèye'],1],
  ['1917-05-01','1916 – 1920','Chinese arbeiders in Europa','Groot-Brittannië en Frankrijk haalden samen ca. 140.000 Chinese arbeiders naar Europa. Ze losten schepen, legden spoorlijnen aan en ruimden na de oorlog slagvelden en munitie op. China hoopte daarmee een plek aan de vredestafel te verdienen.','factory','k','Waarom was China teleurgesteld over de vredesregeling van 1919?',['De Duitse rechten in Shandong gingen naar Japan','China moest herstelbetalingen doen','Hongkong werd Frans'],0],
  ['1917-06-28','juni – juli 1917','Aardappeloproer','In Amsterdam plunderden vooral vrouwen uit arbeiderswijken schuiten met aardappelen die voor het leger bestemd waren. De onrust liep uit op dagenlange rellen, waarbij politie en leger hard optraden en er doden vielen. Het neutrale Nederland had door de oorlog grote voedseltekorten.','coin','n','In welke stad brak in 1917 het bekendste Aardappeloproer uit?',['Rotterdam','Groningen','Amsterdam'],2],
  ['1917-07-31','31 juli – 10 november 1917','Passendale','Bij de Derde Slag om Ieper probeerden Britse en Commonwealth-troepen door de Duitse linies in West-Vlaanderen te breken. Zware regen veranderde het slagveld in een moeras. Na ruim drie maanden namen Canadese troepen het verwoeste dorp Passendale in.','wave','w','Welke troepen veroverden in november 1917 het dorp Passendale?',['Canadese','Franse','Amerikaanse'],0],
  ['1917-11-07','7 november 1917','Oktoberrevolutie','De bolsjewieken van Lenin grepen in Petrograd de macht en zetten de Voorlopige Regering af. Ze beloofden vrede, land voor de boeren en macht voor de sovjets. Kort daarna begon een bloedige burgeroorlog die tot ca. 1921 duurde.','flag','o','Welke partij greep in november 1917 de macht in Rusland?',['De mensjewieken','De bolsjewieken','De sociaal-revolutionairen'],1],
  ['1917-12-09','9 december 1917','Britten nemen Jeruzalem in','Na de doorbraak bij Beersheba en Gaza gaven de Ottomanen Jeruzalem op. Generaal Allenby betrad de stad op 11 december te voet, uit respect voor de heilige plaatsen. Een maand eerder had Groot-Brittannië met de Balfourverklaring steun toegezegd aan een Joods nationaal tehuis in Palestina.','church','m','Hoe betrad generaal Allenby in december 1917 Jeruzalem?',['Te paard aan het hoofd van een optocht','In een pantserwagen','Te voet door de Jaffapoort'],2],
  ['1918-03-03','3 maart 1918','Vrede van Brest-Litovsk','Sovjet-Rusland sloot een aparte vrede met Duitsland en zijn bondgenoten. Het verloor daarbij Polen, de Baltische gebieden, Finland en Oekraïne. Duitsland kon nu troepen naar het Westfront verplaatsen.','scroll','o','Welke Russische onderhandelaar probeerde de vrede te rekken met de leus “geen oorlog, geen vrede”?',['Trotski','Stalin','Kerenski'],0],
  ['1918-03-11','1918 – 1919','Spaanse griep','In drie golven trok een zeer besmettelijke griep over de wereld. Naar schatting stierven 20 tot 50 miljoen mensen, meer dan door de oorlog zelf. Opvallend veel slachtoffers waren jonge volwassenen.','fire','h','Waarom kreeg de griep van 1918 de naam Spaanse griep?',['De ziekte begon in Madrid','De Spaanse pers mocht vrij over de ziekte berichten','Spaanse soldaten verspreidden haar aan het front'],1],
  ['1918-03-21','21 maart – juli 1918','Duits Lenteoffensief','Met troepen van het oostfront deed Duitsland een laatste grote poging de oorlog te winnen voordat de Amerikanen massaal aankwamen. Na een kort, hevig artilleriebombardement braken stoottroepen door de Britse linies. Het leger rukte tientallen kilometers op, maar raakte uitgeput.','sword','w','Wie werd in 1918 aangesteld om de geallieerde legers aan het Westfront samen te leiden?',['Douglas Haig','Ferdinand Foch','John Pershing'],1],
  ['1918-08-08','8 augustus – 11 november 1918','Honderddagenoffensief','Bij Amiens begon een reeks geallieerde aanvallen met tanks, vliegtuigen en artillerie die de Duitse legers steeds verder terugdreef. Ludendorff noemde 8 augustus de zwarte dag van het Duitse leger. Eind september braken de geallieerden door de Hindenburglinie.','sword','w','Bij welke stad begon op 8 augustus 1918 het Honderddagenoffensief?',['Amiens','Verdun','Ieper'],0],
  ['1918-11-03','november 1918','Revolutie in Duitsland','Matrozen in Kiel weigerden nog uit te varen tegen de Britse vloot en kwamen in opstand. Binnen enkele dagen namen arbeiders- en soldatenraden in heel Duitsland de macht over. Op 9 november werd in Berlijn de republiek uitgeroepen.','flag','h','In welke havenstad begon de Duitse revolutie van november 1918?',['Hamburg','Kiel','Bremen'],1],
  ['1918-11-10','10 november 1918','Keizer Wilhelm II vlucht naar Nederland','De Duitse keizer stak bij Eijsden de grens over en vroeg asiel in het neutrale Nederland. Hij verbleef eerst op kasteel Amerongen en kocht later Huis Doorn. Nederland weigerde hem uit te leveren aan de geallieerden.','crown','n','Waar verbleef Wilhelm II direct na zijn vlucht, voordat hij naar Doorn verhuisde?',['Paleis Het Loo','Kasteel De Haar','Kasteel Amerongen'],2],
  ['1918-11-11','11 november 1918','De wapenstilstand','In een treinwagon in het bos bij Compiègne tekende een Duitse delegatie de wapenstilstand met de geallieerden. Om elf uur ’s ochtends zwegen de wapens aan het Westfront. Ook in de laatste uren vielen nog duizenden slachtoffers.','scroll','p','Waar werd de wapenstilstand van 11 november 1918 getekend?',['In het Spiegelpaleis van Versailles','In een treinwagon bij Compiègne','In het stadhuis van Spa'],1],
  ['1918-11-12','12 november 1918','Troelstra’s vergissing','SDAP-leider Pieter Jelles Troelstra riep in november 1918 de arbeiders op de macht te grijpen, naar voorbeeld van de Duitse revolutie. Hij kreeg weinig steun, ook niet van zijn eigen partij. Op het Malieveld betuigden juist tienduizenden mensen hun trouw aan koningin Wilhelmina.','person','n','Waar vond op 18 november 1918 een grote betoging van trouw aan het Koningshuis plaats?',['Op de Dam in Amsterdam','Op het Malieveld in Den Haag','Op de Coolsingel in Rotterdam'],1],
  ['1919-06-28','28 juni 1919','Verdrag van Versailles','Precies vijf jaar na de moord in Sarajevo tekende Duitsland in de Spiegelzaal van Versailles het vredesverdrag. Het verloor grondgebied en al zijn koloniën en moest herstelbetalingen doen. Duitsland mocht niet meeonderhandelen en sprak van een opgelegde vrede.','scroll','p','Hoe groot mocht het Duitse leger volgens het Verdrag van Versailles maximaal zijn?',['100.000 man','250.000 man','500.000 man'],0],
  ['1920-01-10','10 januari 1920','De Volkenbond','De Volkenbond moest landen helpen conflicten vreedzaam op te lossen, zodat een nieuwe wereldoorlog voorkomen kon worden. De zetel kwam in Genève. De Verenigde Staten, waarvan de president het plan had bedacht, werden nooit lid.','globe','p','Welk land werd nooit lid van de Volkenbond, hoewel zijn president het idee had gelanceerd?',['Frankrijk','Groot-Brittannië','De Verenigde Staten'],2]
]);
