 bronnen: [['Wikipedia: Arabische Opstand',W('Arabische Opstand 1916')],['Wikipedia: Sykes-Picotverdrag',W('Sykes-Picotverdrag')],['Imperial War Museums','https://www.iwm.org.uk/']]
